record.field:
for project in records:
    if project.trang_thai == 'hoan_thanh' and project.khach_hang_id:
        if project.khach_hang_id:
            # Tạo lịch hẹn
            env['lich_hen'].create({
                'khach_hang_id': project.khach_hang_id.id,
                'nhan_vien_id': project.phu_trach_id.id if project.phu_trach_id else False,
                'thoi_gian': datetime.datetime.now() + datetime.timedelta(days=7),
                'dia_diem': 'Văn phòng công ty',
                'noi_dung': f'Tổng kết và bàn giao dự án {project.name}',
                'trang_thai': 'du_kien',
            })
